const tage = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag'];
const planung = { Montag: [], Dienstag: [], Mittwoch: [], Donnerstag: [], Freitag: [] };
const MAX_PLAETZE = 12;

// Liste der Seniors (jeder, der nicht hier drin steht, wird als Praktikant gewertet)
const SENIORS_LIST = [
  "Senior 1", "Senior 2", "Senior 3", 
  "Senior 4", "Senior 5", "Senior 6", 
  "Senior 7", "Senior 8", "Senior 9",
  "Senior 10", "Senior 11", "Senior 12", 
  "Senior 13", "Senior 14"
];

// 1. Daten sammeln (Wer ist im Office?)
for (const item of $input.all()) {
  tage.forEach(tag => {
    const status = (item.json[tag] || "").toLowerCase();
    // Wir zählen jeden, bei dem "office" im Status vorkommt
    if (status.includes('office')) {
      planung[tag].push(item.json.Name);
    }
  });
}

// 2. Slack-Nachricht zusammenbauen
let slackText = "Hallo zusammen <!channel>! 👋\nAnbei die Office-Besetzung für die nächste Woche:\n\n";

tage.forEach(tag => {
  const tagesListe = planung[tag];
  const belegtePlaetze = tagesListe.length;

  // Warnmeldung generieren, falls das Limit erreicht oder überschritten ist
  let warnung = "";
  if (belegtePlaetze === MAX_PLAETZE) {
    warnung = " ⚠️ *VOLL BELEGT!*";
  } else if (belegtePlaetze > MAX_PLAETZE) {
    warnung = ` 🚨 *ÜBERBELEGT!* (um ${belegtePlaetze - MAX_PLAETZE} Personen)`;
  }

  // Zeile formatieren: Wochentag (X/12): + Warnung
  slackText += `*${tag}* (${belegtePlaetze}/${MAX_PLAETZE}):${warnung}\n`;

  if (belegtePlaetze === 0) {
    // Falls niemand da ist
    slackText += `_Keiner im Büro_\n\n`;
  } else {
    // Aufteilung in Seniors und Praktikanten
    const seniors = tagesListe.filter(name => SENIORS_LIST.includes(name));
    const praktikanten = tagesListe.filter(name => !SENIORS_LIST.includes(name));

    // Kategorien nur ausgeben, wenn auch Personen darin vorhanden sind (mit fettgedruckten Labels)
    if (praktikanten.length > 0) {
      slackText += `*Praktikanten:* ${praktikanten.join(', ')}\n`;
    }
    if (seniors.length > 0) {
      slackText += `*Seniors:* ${seniors.join(', ')}\n`;
    }

    // Leere Zeile als Abstand zum nächsten Tag
    slackText += `\n`; 
  }
});

// 3. Link zur Tabelle anhängen
slackText += "Weitere Informationen findest Du hier:\n";
slackText += "https://docs.google.com/spreadsheets/d/DEINE_GOOGLE_SHEET_ID/edit#gid=0";

return { 
  nachricht: slackText 
};

const finalData = {}; 
const tageMapping = { 
  'mo': 'Montag', 'montag': 'Montag',
  'di': 'Dienstag', 'dienstag': 'Dienstag',
  'mi': 'Mittwoch', 'mitt': 'Mittwoch', 'mittwoch': 'Mittwoch',
  'do': 'Donnerstag', 'donn': 'Donnerstag', 'donnerstag': 'Donnerstag',
  'fr': 'Freitag', 'freitag': 'Freitag',
  'sa': 'Samstag', 'samstag': 'Samstag',
  'so': 'Sonntag', 'sonntag': 'Sonntag'
};

const dayIndices = {
  'mo': 0, 'montag': 0,
  'di': 1, 'dienstag': 1,
  'mi': 2, 'mitt': 2, 'mittwoch': 2,
  'do': 3, 'donn': 3, 'donnerstag': 3,
  'fr': 4, 'freitag': 4,
  'sa': 5, 'samstag': 5,
  'so': 6, 'sonntag': 6
};
const tageArrayShort = ['mo', 'di', 'mi', 'do', 'fr', 'sa', 'so'];

// --- HILFSFUNKTION: STATUS-VALIDIERUNG ---
function isValidStatus(statusText, fullLine, isColonFormat) {
  if (!statusText) return false;
  const cleanText = statusText.trim();

  if (!isColonFormat) {
    if (cleanText.split(/\s+/).length > 15 || cleanText.length > 100) return false;
  }

  const textToCheck = (fullLine || cleanText).toLowerCase();

  // ERWEITERT: Wörter, die typisch für normale Chat-Nachrichten sind
  const ignoreWords = [
    'eintragen', 'tragt', 'denkt dran', 'bitte', 'vergessen', 'erinnerung', 
    'soll man', 'trikot', 'nachricht', 'channel', 'bearbeiten', 'eigene', 
    'einfach', 'löschen', 'thread', 'posten'
  ];

  if (ignoreWords.some(word => textToCheck.includes(word))) return false;

  return true;
}

// --- ZEIT-FILTER LOGIK ---
const heute = new Date();
const aktuellerWochentag = heute.getDay(); 
const tageSeitFreitag = (aktuellerWochentag + 2) % 7; 
const letzterFreitag = new Date(heute);
letzterFreitag.setDate(heute.getDate() - tageSeitFreitag);
letzterFreitag.setHours(0, 0, 0, 0);

for (const item of $input.all()) {
  const slackTsRaw = item.json.ts;
  const slackTsMs = parseFloat(slackTsRaw) * 1000;

  if (slackTsMs < letzterFreitag.getTime()) continue;

  let nameRaw = item.json.profile?.real_name || item.json.real_name || item.json.user || "Unbekannt";
  const name = nameRaw.trim(); 

  const nameKey = name.toLowerCase(); 

  // --- AGGRESSIVER BOT-FILTER ---
  if (
    nameKey === 'n8n' || 
    nameKey.includes('bot') || 
    item.json.bot_id !== undefined || 
    item.json.bot_profile !== undefined || 
    item.json.subtype === 'bot_message'
  ) {
    continue;
  }

  let text = item.json.text || "";

  // --- ANNOUNCEMENT FILTER ---
  const lowerTextGlobal = text.toLowerCase();
  if (['@channel', '<!channel>', '@here', '<!here>'].some(word => lowerTextGlobal.includes(word))) {
    continue;
  }

  // --- SLACK EMOJI BEREINIGUNG ---
  text = text.replace(/:[a-z0-9_+-]+:/gi, '');

  text = text.replace(/\bhome\s*office\b/gi, 'HO');

  const hatWochentag = Object.keys(tageMapping).some(k => 
    new RegExp(`\\b${k}\\b`, 'i').test(text.toLowerCase())
  );
  if (!hatWochentag || !text) continue;

  const dateObj = new Date(slackTsMs);
  const datumString = dateObj.toLocaleDateString('de-DE', {
    day: '2-digit', month: '2-digit', year: 'numeric'
  });

  const row = { 
    Name: name, 
    Datum_Meldung: datumString,
    Montag: "", Dienstag: "", Mittwoch: "", Donnerstag: "", Freitag: "", Samstag: "", Sonntag: "",
    _ts: slackTsMs 
  };

  const rangeRegex = /\b(mo|montag|di|dienstag|mi|mitt|mittwoch|do|donn|donnerstag|fr|freitag|sa|samstag|so|sonntag)\s*(?:-|–|—|bis)\s*(mo|montag|di|dienstag|mi|mitt|mittwoch|do|donn|donnerstag|fr|freitag|sa|samstag|so|sonntag)\b/gi;

  text = text.replace(rangeRegex, (match, p1, p2) => {
    const start = dayIndices[p1.toLowerCase()];
    const end = dayIndices[p2.toLowerCase()];
    if (start !== undefined && end !== undefined && start < end) {
      return tageArrayShort.slice(start, end + 1).join(' ');
    }
    return match;
  });

  const zeilen = text.split('\n');
  zeilen.forEach(zeile => {
    const lowerZeile = zeile.toLowerCase();

    if (zeile.includes(':')) {
      const parts = zeile.split(':');
      const tageTeil = parts[0].toLowerCase();
      const status = parts.slice(1).join(':').trim(); 

      Object.keys(tageMapping).forEach(k => {
        if (new RegExp(`\\b${k}\\b`, 'i').test(tageTeil)) {
          if (isValidStatus(status, zeile, true)) {
            row[tageMapping[k]] = status;
          }
        }
      });
    } else {
      Object.keys(tageMapping).forEach(k => {
        if (new RegExp(`\\b${k}\\b`, 'i').test(lowerZeile)) {
          let extrakt = zeile.replace(/\b(mo|montag|di|dienstag|mi|mitt|mittwoch|do|donn|donnerstag|fr|freitag|sa|samstag|so|sonntag)\b/gi, '')
                             .replace(/\b(ab|am|von|für)\b/gi, '') 
                             .replace(/[,.‑–—-]/g, '')
                             .replace(/\bbis\b/gi, '')
                             .replace(/\s{2,}/g, ' ') 
                             .trim();

          if (extrakt && isValidStatus(extrakt, zeile, false)) {
            row[tageMapping[k]] = extrakt;
          }
        }
      });
    }
  });

  const hatInhalt = Object.keys(row).some(k => 
    k !== 'Name' && k !== 'Datum_Meldung' && k !== '_ts' && row[k] !== ""
  );

  // --- NEU: MERGE-LOGIK STATT STRIKTEM ÜBERSCHREIBEN ---
  if (hatInhalt) {
    if (!finalData[nameKey]) {
      // Neuer Eintrag
      finalData[nameKey] = row;
    } else {
      // Eintrag existiert bereits. Wir prüfen, welche Nachricht jünger ist.
      if (finalData[nameKey]._ts < row._ts) {
        // Die NEUE Nachricht ist jünger. Wir überschreiben nur die Tage, die in der neuen Nachricht stehen.
        Object.keys(row).forEach(key => {
          if (key !== 'Name' && key !== 'Datum_Meldung' && key !== '_ts' && row[key] !== "") {
            finalData[nameKey][key] = row[key];
          }
        });
        finalData[nameKey]._ts = row._ts;
        finalData[nameKey].Datum_Meldung = row.Datum_Meldung;
      } else {
        // Die BEREITS GESPEICHERTE Nachricht ist jünger. Wir füllen nur Lücken mit den alten Daten auf.
        Object.keys(row).forEach(key => {
          if (key !== 'Name' && key !== 'Datum_Meldung' && key !== '_ts' && finalData[nameKey][key] === "" && row[key] !== "") {
            finalData[nameKey][key] = row[key];
          }
        });
      }
    }
  }
}

const finalArray = Object.values(finalData).map(row => {
  delete row._ts;
  return row;
});

return finalArray;
